4	  opencodeConfig = {
5	    "$schema" = "https://opencode.ai/config.json";
6	    # opencode-claude-memory reads/writes Claude Code's own memory store
7	    # (~/.claude/projects/<sanitized canonical git root>/memory/), so both CLIs
8	    # share one set of memories. Pinned because it injects a system prompt and
9	    # runs a per-turn recall subagent. That subagent is pinned via
10	    # OPENCODE_MEMORY_RECALL_MODEL in the wrapper below — to the cheapest Coding
11	    # Plan model rather than the session's, since recall fires every turn.
12	    # Set OPENCODE_MEMORY_IGNORE=1 to disable injection.
13	    plugin = [ "opencode-model-stats@0.2.3" "opencode-claude-memory@1.7.3" ];
14	    disabled_providers = [ "opencode" "zai" ];
15	    # Pin the default: unset, opencode picks one, and non-interactive launches
16	    # (drovr's review panel) inherit whatever that is.
17	    #
18	    # Z.ai's hosted GLM rather than the local model. lemonade serves 4 slots off
19	    # one GPU, and with hakobiya on the same router a turn queues behind
20	    # multi-minute triage requests -- a one-token reply measured 3m14s, and
21	    # decode falls to 2-4 t/s under load against 31 t/s idle. ko-ag is still
22	    # registered below, so `/models` can still reach the local box on purpose.
23	    model = "zai-coding-plan/glm-5.3";
24	    # Title generation and other throwaway calls. Unset, these inherit `model`
25	    # above and bill the flagship for a six-word title.
26	    small_model = "zai-coding-plan/glm-5.3-flash";
27	    provider = {
28	      mcloud = {
29	        npm = "@ai-sdk/openai-compatible";
30	        name = "Modular (internal)";
31	        # baseURL injected at activation from the sops secret
32	        # ~/.config/opencode/mcloud-base-url so the private hostname never
33	        # appears in the committed config.
34	        options = { };
35	        models = {
36	          "MiniMaxAI/MiniMax-M3" = { name = "MiniMax M3"; };
37	        };
38	      };
39	      "ko-ag" = {
40	        npm = "@ai-sdk/openai-compatible";
41	        name = "ko.ag";
42	        options = {
43	          # LAN address of the in-cluster litellm router (Cilium LoadBalancer,
44	          # L2-announced). ai.ko.ag is GONE: it fronted this same router through
45	          # a Workers façade and CF AI Gateway, and 524'd structurally because
46	          # litellm emits no bytes until its upstream produces a first token,
47	          # which Cloudflare reads as a dead origin. See the kube repo's
48	          # docs/litellm-access.md.
49	          #
50	          # Plain HTTP, and the API key crosses the LAN in cleartext. Acceptable
51	          # here because the only paths to this address are the home LAN and the
52	          # 10.9.0.0/24 WireGuard VPN, and the key authorizes inference on a
53	          # self-hosted model. Fixing it means a TLS sidecar on the Service, not
54	          # a change on this side.
55	          baseURL = "http://10.0.7.240:4000/v1";
56	        };
57	        # `glm` is litellm's own model-group name, not a lemonade id: it routes
58	        # lemonade -> Z.ai Coding Plan -> OpenRouter, so a dead local model
59	        # fails over instead of erroring. The old lowercase lemonade id still
60	        # works via model_group_alias, but that alias exists to be retired.
61	        models = {
62	          "glm" = { name = "GLM (lemonade -> Z.ai -> OpenRouter)"; };
63	        };
64	      };
65	      # Built-in models.dev providers; apiKey injected at activation from sops.
66	      "zai-coding-plan" = {
67	        npm = "@ai-sdk/openai-compatible";
68	        name = "Z.AI Coding Plan";
69	        options = {
70	          baseURL = "https://api.z.ai/api/coding/paas/v4";
