75	  configTemplate = pkgs.writeText "opencode.json.tmpl" (builtins.toJSON opencodeConfig);
76	
77	  # opencode-model-stats adds `session_id`/`message_id` headers alongside the
78	  # canonical `x-opencode-*` forms. Modular's edge proxy (Envoy) 400s any
79	  # request with an underscore-named header before it reaches the model server.
80	  # Strip those two lines from the cached plugin source — the x- prefixed
81	  # headers carry the same data.
82	  patchModelStats = pkgs.writeShellScript "opencode-patch-model-stats" ''
83	    set -eu
84	    shopt -s nullglob
85	    for f in "$HOME"/.cache/opencode/packages/opencode-model-stats@*/node_modules/opencode-model-stats/src/server.ts; do
86	      if ${pkgs.gnugrep}/bin/grep -q '\["session_id"\]\|\["message_id"\]' "$f"; then
87	        ${pkgs.gnused}/bin/sed -i \
88	          -e '/output\.headers\["session_id"\] *= *ctx\.sessionID/d' \
89	          -e '/output\.headers\["message_id"\] *= *ctx\.messageID/d' \
90	          "$f"
91	      fi
92	    done
