2	  inputs = {
3	    nixpkgs.url = "github:NixOS/nixpkgs/nixpkgs-unstable";
4	    home-manager = {
5	      url = "github:nix-community/home-manager";
6	      inputs.nixpkgs.follows = "nixpkgs";
7	    };
8	    nix-darwin = {
9	      url = "github:LnL7/nix-darwin";
10	      inputs.nixpkgs.follows = "nixpkgs";
11	    };
12	    sops-nix = {
13	      url = "github:Mic92/sops-nix";
14	      inputs.nixpkgs.follows = "nixpkgs";
15	    };
16	    walker.url = "github:abenz1267/walker";
17	    nixgl.url = "github:guibou/nixGL";
18	    explore-mcp.url = "github:sauyon/explore-mcp";
19	    explore-mcp.inputs.nixpkgs.follows = "nixpkgs";
20	    # drovr — CLI for single-writer/compressed-handoff agent phases; ships the
21	    # `drovr` binary plus drovr:* Claude skills under share/drovr/.
22	    drovr.url = "git+https://forge.ko.ag/drovr/drovr.git";
23	    drovr.inputs.nixpkgs.follows = "nixpkgs";
24	    # Terminal diff viewer for agent changesets; ships a `hunk-review` Claude
25	    # skill under `${hunk}/skills/`.
26	    hunk.url = "github:modem-dev/hunk";
27	    # Matt Pocock's agent skills. Not a flake — a plain tree of SKILL.md
28	    # bundles under skills/<category>/<name>/, consumed by path below.
29	    mattpocock-skills.url = "github:mattpocock/skills";
30	    mattpocock-skills.flake = false;
31	    # Seamless OIDC SSH gate (gate binary + nixos/darwin modules).
32	    ssh-oidc.url = "git+https://codeberg.org/sauyon/ssh-oidc";
33	  };
