35	  outputs = { nixpkgs, home-manager, nix-darwin, sops-nix, walker, nixgl, explore-mcp, drovr, hunk, mattpocock-skills, ssh-oidc, ... }:
36	  let
37	    mkHome = system: machine: home-manager.lib.homeManagerConfiguration {
38	      pkgs = nixpkgs.legacyPackages.${system};
39	      extraSpecialArgs = {
40	        inherit sops-nix walker nixgl explore-mcp drovr hunk mattpocock-skills machine;
41	        inherit system;
42	      };
43	      modules = [ ./home.nix ];
44	    };
45	    linuxHome = mkHome "x86_64-linux";
46	  in {
47	    homeConfigurations.utsuho = linuxHome {
48	      hostname = "utsuho";
49	      gui = true;
50	      gpu = "amd";
51	    };
52	    homeConfigurations.setsuna = linuxHome {
53	      hostname = "setsuna";
54	      gui = true;
55	    };
56	    homeConfigurations.fujiwara = linuxHome {
57	      hostname = "fujiwara";
58	      # Headless: the box has an HDMI display wired up, but no graphical session
59	      # has run on it since Jun 2025. Dropping the desktop stack (hyprland,
60	      # waybar, walker, kanshi, portals) rather than leaving units to fail at
61	      # every activation. Flip back to true if it becomes a workstation again.
62	      gui = false;
63	      gpu = "amd";
64	    };
65	    homeConfigurations.mari = mkHome "aarch64-darwin" {
66	      hostname = "mari";
67	      gui = true;
68	    };
69	
70	    darwinConfigurations.mari = nix-darwin.lib.darwinSystem {
71	      system = "aarch64-darwin";
72	      modules = [
73	        sops-nix.darwinModules.sops
74	        ssh-oidc.darwinModules.default
75	        ({ config, ... }: {
76	          programs.zsh.enable = true;
77	          nix.enable = true;
78	          nix.settings.experimental-features = [ "nix-command" "flakes" ];
79	
80	          # Self-hosted attic binary cache (kube cluster); signing key is public.
81	          # Assumes nix-darwin manages nix (nix.enable = true). If mari moves to
82	          # Determinate Nix, relocate this to /etc/determinate like the Linux boxes.
83	          nix.settings.extra-substituters = [ "https://attic.ko.ag/kube" ];
84	          nix.settings.extra-trusted-public-keys = [ "kube:REDACTED" ];
85	          # Private cache → read token via netrc, rendered as root by sops-nix.
86	          sops.secrets.atticPullToken = { };
87	          sops.templates."attic-netrc".content = "machine attic.ko.ag password ${config.sops.placeholder.atticPullToken}";
88	          nix.settings.netrc-file = config.sops.templates."attic-netrc".path;
89	
90	          # Remote builder: Linux boxes delegate aarch64-darwin builds here over
91	          # Tailscale. The gate's ForceCommand would hijack the non-interactive
92	          # `nix-store --serve` path if it shared the human `sauyon` login, so the
93	          # builder connects as the dedicated `nixremote` user, carved out by the
94	          # ssh-oidc-gate Match block below. Both users must be nix trusted-users.
95	          # DEPLOY: update the Linux boxes' nix.custom.conf `builders` line from
96	          #   ssh-ng://sauyon@100.106.204.103 ...   to   ssh-ng://nixremote@100.106.204.103 ...
97	          # and ensure the builder pubkey is in /run/secrets/ssh-oidc-builder-key.pub here.
98	          nix.settings.trusted-users = [ "sauyon" "nixremote" ];
99	          system.stateVersion = 6;
100	          nixpkgs.hostPlatform = "aarch64-darwin";
101	
102	          environment.etc."sops/age-unused.txt".text = "";
103	          sops.defaultSopsFile = ./secrets.yaml;
104	          sops.age.keyFile = "/etc/sops/age-unused.txt";
105	          sops.age.sshKeyPaths = [ ];
106	          sops.gnupg.sshKeyPaths = [ ];
107	          sops.environment.GOOGLE_APPLICATION_CREDENTIALS = "/Users/sauyon/.config/sops/gcp-key.json";
108	          # Human key(s). With the OIDC gate active, its always-accept
109	          # AuthorizedKeysCommand (not this file) decides the publickey stage for
110	          # the `sauyon` login; the builder carve-out is handled separately
111	          # (sshOidcBuilderKey, below).
112	          sops.secrets."ssh-authorized-keys-sauyon" = {
113	            mode = "0644";
114	          };
115	
116	          # ssh-oidc gate. Shared bearer token for the enrollment service;
117	          # rendered by sops-nix, read by the gate at runtime (never in the store).
118	          # NOTE: add an `sshOidcToken` key to secrets.yaml (the gate's service token).
119	          sops.secrets.sshOidcToken = {
120	            # Readable by the login (sauyon) user — the gate runs as that user.
121	            mode = "0444";
122	          };
123	          # The remote-builder's PUBLIC key, in its own authorized_keys file, used by
124	          # the gate's Match-block carve-out for the `nixremote` builder user.
125	          # NOTE: add an `sshOidcBuilderKey` key to secrets.yaml (the builder pubkey,
126	          # the same value currently in `mariBuilderKey`'s public half).
127	          sops.secrets.sshOidcBuilderKey = {
128	            mode = "0444";
129	          };
130	
131	          services.ssh-oidc-gate = {
132	            enable = true;
133	            serviceUrl = "https://ssh-oidc.ko.ag";
134	            tokenFile = config.sops.secrets.sshOidcToken.path;
135	            # Remote-build carve-out (MANDATORY): the nix daemon connects as `nixremote`
136	            # and bypasses the ForceCommand gate via this Match block.
137	            builderMatchUser = "nixremote";
138	            builderAuthorizedKeysFile = config.sops.secrets.sshOidcBuilderKey.path;
139	          };
140	
141	          # Dedicated, no-login builder account the nix daemon SSHes in as;
142	          # nix-darwin creates it (knownUsers drives dscl). Must be a trusted-user
143	          # (above) to run builds; the gate carve-out lets its key skip the OIDC
144	          # ForceCommand.
145	          users.knownUsers = [ "nixremote" ];
146	          users.users.nixremote = {
147	            uid = 541;
148	            gid = 541;
149	            home = "/var/empty";
150	            shell = "/usr/bin/false";
151	            description = "nix remote builder";
152	            isHidden = true;
153	          };
154	          users.knownGroups = [ "nixremote" ];
155	          users.groups.nixremote = {
156	            gid = 541;
157	            description = "nix remote builder";
158	          };
159	
160	          services.openssh = {
161	            enable = true;
162	            # The gate module appends AuthenticationMethods/AuthorizedKeysCommand/
163	            # ForceCommand/ExposeAuthInfo (+ the nixremote Match carve-out) via mkAfter.
164	            # Keep only host-level policy here; do NOT set AuthorizedKeysFile (the gate
165	            # sets it to `none` globally and to the builder key inside the Match block).
166	            extraConfig = ''
167	              PermitRootLogin no
168	              PasswordAuthentication no
169	            '';
170	          };
171	        })
172	      ];
173	    };
174	
175	    # Patched tailscaled for the Linux boxes. Tailscale SSH creates a logind
176	    # session before the user's shell runs, which for a systemd-homed user whose
177	    # LUKS home is still locked makes logind start user@<uid>.service against
178	    # homed's fallback home ("/") -- permanently breaking that user manager's
179	    # unit search path for the rest of the boot. See the patch header.
180	    #
181	    # Only `patches` is overridden, deliberately: buildGoModule builds its
182	    # goModules derivation from src + go.mod/go.sum, and this patch touches a
183	    # single .go file, so vendoring is unaffected and no vendorHash change is
184	    # needed. Overriding `src` to a different tailscale release would NOT be
185	    # safe this way -- goModules would still be built from the original source.
186	    #
187	    # Deployed by system/deploy, which builds this, pins it with a root-owned GC
188	    # root outside the encrypted home (so it survives `nix-collect-garbage` and
189	    # is readable at boot before /home/sauyon is unlocked), and points
190	    # /etc/systemd/system/tailscaled.service at it.
191	    packages.x86_64-linux.tailscale-patched =
192	      let
193	        pkgs = nixpkgs.legacyPackages.x86_64-linux;
194	      in
195	      pkgs.tailscale.overrideAttrs (old: {
196	        patches = (old.patches or [ ]) ++ [
197	          ./patches/tailscale-ssh-skip-logind-session-for-locked-homed-user.patch
198	        ];
199	      });
200	  };
201	}
